def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    c=Counter(v for r in g for v in r)
    bg=c.most_common(1)[0][0]
    best=None
    for col,_ in c.most_common():
        if col==bg: continue
        pos=[(i,j) for i in range(H) for j in range(W) if g[i][j]==col]
        rs=[p[0] for p in pos]; cs=[p[1] for p in pos]
        if min(rs)>0 and max(rs)<H-1 and min(cs)>0 and max(cs)<W-1:
            best=col;break
    bcol=best
    rs=[p[0] for p in [(i,j) for i in range(H) for j in range(W) if g[i][j]==bcol]]
    cs=[p[1] for p in [(i,j) for i in range(H) for j in range(W) if g[i][j]==bcol]]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[[bg]*W for _ in range(H)]
    vals=[];pts=[]
    for (i,j) in [(r0+1,c0+1),(r0+1,c1-1),(r1-1,c0+1),(r1-1,c1-1)]:
        vals.append(g[i][j]); pts.append((i,j))
    for idx,(v,(i,j)) in enumerate(zip(vals,pts)):
        if i==r0+1 and j==c0+1: oi,oj=r1+1+(r1-i),c1+1+(c1-j)
        elif i==r0+1 and j==c1-1: oi,oj=r1+1+(r1-i),c0-1-(c0-j)
        elif i==r1-1 and j==c0+1: oi,oj=r0-1-(r0-i),c1+1+(c1-j)
        else: oi,oj=r0-1-(r0-i),c0-1-(c0-j)
        out[oi][oj]=v
    return out
